Develop a real-time guest messaging system with the following features:
1. Message submission form with sender information
2. Real-time message display with animations
3. Message moderation capabilities (for wedding couple)
4. Support for different message lengths with adaptive UI

Implement using Firebase Firestore or a similar real-time database for message storage and retrieval. Create a MessageRepository to handle data operations.

Example implementation:
```dart
class MessageScreen extends StatefulWidget {
  @override
  _MessageScreenState createState() => _MessageScreenState();
}

class _MessageScreenState extends State<MessageScreen> {
  final MessageRepository _repository = GetIt.instance<MessageRepository>();
  final TextEditingController _nameController = TextEditingController();
  final TextEditingController _messageController = TextEditingController();
  late Stream<List<MessageModel>> _messagesStream;

  @override
  void initState() {
    super.initState();
    _messagesStream = _repository.getMessagesStream();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Column(
        children: [
          Expanded(
            child: StreamBuilder<List<MessageModel>>(
              stream: _messagesStream,
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return Center(child: CircularProgressIndicator());
                }

                final messages = snapshot.data ?? [];
                return ListView.builder(
                  itemCount: messages.length,
                  itemBuilder: (context, index) => MessageCard(message: messages[index]),
                );
              },
            ),
          ),
          MessageComposer(
            nameController: _nameController,
            messageController: _messageController,
            onSend: _sendMessage,
          ),
        ],
      ),
    );
  }

  Future<void> _sendMessage() async {
    if (_nameController.text.isNotEmpty && _messageController.text.isNotEmpty) {
      await _repository.addMessage(
        MessageModel(
          sender: _nameController.text,
          content: _messageController.text,
          timestamp: DateTime.now(),
        ),
      );
      _messageController.clear();
    }
  }
}
```

