```dart
class EditorScreen extends StatefulWidget {
  @override
  _EditorScreenState createState() => _EditorScreenState();
}

class _EditorScreenState extends State<EditorScreen> {
  final List<CustomWidgetModel> _widgets = [];
  CustomWidgetModel? _selectedWidget;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Row(
        children: [
          // Widget palette
          WidgetPalette(
            onWidgetSelected: _addWidget,
          ),
          // Editor canvas
          Expanded(
            child: Stack(
              children: [
                // Background grid
                GridPaper(
                  color: Colors.grey.withOpacity(0.2),
                  divisions: 1,
                  subdivisions: 1,
                ),
                // Placed widgets
                ..._widgets.map((widget) => DraggableWidget(
                  widget: widget,
                  isSelected: _selectedWidget == widget,
                  isDraggable: _isWidgetDraggable(widget),
                  onTap: () => setState(() => _selectedWidget = widget),
                  onDragEnd: (offset) => _updateWidgetPosition(widget, offset),
                  onLockStateChanged: (isLocked) => _updateWidgetLockState(widget, isLocked),
                )),
              ],
            ),
          ),
          // Property editor
          if (_selectedWidget != null)
            PropertyEditor(
              widget: _selectedWidget!,
              onPropertyChanged: _updateWidgetProperty,
            ),
        ],
      ),
      floatingActionButton: FloatingActionButton(
        child: Icon(Icons.save),
        onPressed: _saveLayout,
      ),
    );
  }

  bool _isWidgetDraggable(CustomWidgetModel widget) {
    // For map widgets, check lock state
    if (widget.type == WidgetType.map) {
      return !(widget.properties['isLocked'] ?? true);
    }
    // Other widgets are always draggable
    return true;
  }

  void _addWidget(WidgetType type) {
    setState(() {
      Map<String, dynamic> properties = {};

      // Set default properties based on widget type
      if (type == WidgetType.map) {
        properties['isLocked'] = true;
      }

      _widgets.add(CustomWidgetModel(
        type: type,
        position: Offset(100, 100),
        size: Size(200, 100),
        properties: properties,
      ));
    });
  }

  void _updateWidgetPosition(CustomWidgetModel widget, Offset position) {
    setState(() {
      final index = _widgets.indexOf(widget);
      _widgets[index] = widget.copyWith(position: position);
    });
  }

  void _updateWidgetProperty(String property, dynamic value) {
    if (_selectedWidget != null) {
      setState(() {
        final index = _widgets.indexOf(_selectedWidget!);
        final updatedProperties = Map<String, dynamic>.from(_selectedWidget!.properties);
        updatedProperties[property] = value;
        _widgets[index] = _selectedWidget!.copyWith(properties: updatedProperties);
        _selectedWidget = _widgets[index];
      });
    }
  }

  void _updateWidgetLockState(CustomWidgetModel widget, bool isLocked) {
    setState(() {
      final index = _widgets.indexOf(widget);
      final updatedProperties = Map<String, dynamic>.from(widget.properties);
      updatedProperties['isLocked'] = isLocked;
      _widgets[index] = widget.copyWith(properties: updatedProperties);
      if (_selectedWidget == widget) {
        _selectedWidget = _widgets[index];
      }
    });
  }

  Future<void> _saveLayout() async {
    // Save layout to repository
  }
}
```

