class OptimizedImage extends StatelessWidget {
  final String imageUrl;
  final double width;
  final double height;

  const OptimizedImage({
    Key? key,
    required this.imageUrl,
    this.width = double.infinity,
    this.height = 200,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
