      fit: BoxFit.cover,
      placeholder: (context, url) => ShimmerPlaceholder(width: width, height: height),
      errorWidget: (context, url, error) => Icon(Icons.error),
      memCacheWidth: (width * MediaQuery.of(context).devicePixelRatio).round(),
      memCacheHeight: (height * MediaQuery.of(context).devicePixelRatio).round(),
    );
  }
}

// Widget rebuilding optimization
class MemoizedWidget extends StatelessWidget {
  final String data;

  const MemoizedWidget({Key? key, required this.data}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Text(data);
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is MemoizedWidget && other.data == data;
  }

  @override
  int get hashCode => data.hashCode;
}
