class DraggableWidgetController extends ChangeNotifier {
  Offset _position = Offset.zero;

  Offset get position => _position;

  void updatePosition(Offset newPosition, Size canvasSize, Size widgetSize) {
    // Boundary detection
    final double maxX = canvasSize.width - widgetSize.width;
    final double maxY = canvasSize.height - widgetSize.height;

    _position = Offset(
      newPosition.dx.clamp(0, maxX),
      newPosition.dy.clamp(0, maxY),
    );

    notifyListeners();
  }
}
```

For visual glitches during drag:
```dart
class DraggableWidget extends StatefulWidget {
  @override
  _DraggableWidgetState createState() => _DraggableWidgetState();
}

class _DraggableWidgetState extends State<DraggableWidget> {
  bool _isDragging = false;

  @override
  Widget build(BuildContext context) {
    final controller = Provider.of<DraggableWidgetController>(context);

    return AnimatedOpacity(
      opacity: _isDragging ? 0.8 : 1.0,
      duration: Duration(milliseconds: 150),
      child: Draggable(
        feedback: Material(
          color: Colors.transparent,
          child: widget.child,
        ),
        childWhenDragging: Opacity(
          opacity: 0.3,
          child: widget.child,
        ),
        onDragStarted: () => setState(() => _isDragging = true),
        onDragEnd: (details) {
          setState(() => _isDragging = false);
          controller.updatePosition(details.offset, canvasSize, widgetSize);
        },
        child: widget.child,
      ),
    );
  }
}

