```dart
class UrlParameterHandler {
  static Map<String, String> parseUrlParameters(Uri uri) {
    return uri.queryParameters;
  }

  static void applyParametersToApp(Map<String, String> parameters, BuildContext context) {
    if (parameters.containsKey('venue')) {
      final venue = parameters['venue'];
      if (['Malaysia', 'Singapore', 'Korea', 'All'].contains(venue)) {
        context.read<VenueProvider>().setVenue(venue!);
      }
    }

    if (parameters.containsKey('lang')) {
      final lang = parameters['lang'];
      if (['en', 'ko'].contains(lang)) {
        context.read<LanguageProvider>().setLanguage(lang!);
      }
    }
  }
}

